 const {$,$$,esc}=api,short=id=>id?.split('::').at(-1)||'',display=t=>(({long:'정수',int:'정수',double:'실수',float:'실수',bool:'조건',string:'글자',void:'없음'})[t.replace(/\[\]$/,'')]||short(t))+(t.endsWith('[]')?' 여러 개':'');
