  document.addEventListener('pointerdown',e=>{if(!root.contains(e.target)&&!anchor.contains(e.target)&&!picker?.root.contains(e.target))close();},{capture:true,signal:events.signal});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!picker){e.preventDefault();close();if(anchor.isConnected)anchor.focus({preventScroll:true});}},{signal:events.signal});document.addEventListener('scroll',e=>{if(!root.contains(e.target)){closePicker();position();}},{capture:true,signal:events.signal});window.addEventListener('resize',()=>{closePicker();position();},{signal:events.signal});observer=new ResizeObserver(position);observer.observe(root);lifetime=new MutationObserver(()=>{if(!owns())close();});lifetime.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['hidden','class']});position();description.focus({preventScroll:true});
